// Shared source, embedded into each workflow by the exporter. No secrets in items.
const SB_URL='https://abujjbkbbiumxrokozph.supabase.co';
const N8N_URL='https://n8n.higher.boutique';
const uuid=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(value||''));
const sbHeaders={apikey:$env.SB_KEY,'Content-Type':'application/json'};
const pfHeaders={Authorization:'Bearer '+$env.PRINTFUL_TOKEN,'X-PF-Store-Id':String($env.PF_STORE_ID),'Content-Type':'application/json'};
const request=async options=>{
  let response;
  try{response=await this.helpers.httpRequest({...options,json:options.json!==false,
    returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:options.timeout||30000});}
  catch{throw new Error('transport_'+String(options.method||'GET').toLowerCase());}
  if(response.statusCode>=400){
    // 05/11 : un fournisseur qui refuse DIT pourquoi. Sans ce detail, toute panne externe
    // se resume a `http_404` et on cherche a l'aveugle. 110 caracteres au plus :
    // `streetwear_fail` tronque le code a 160.
    let detail='';
    try{const b=response.body;
      detail=String(typeof b==='string'?b:(b&&b.error&&b.error.message)||(b&&b.detail)||(b&&b.message)||JSON.stringify(b)||'').replace(/\s+/g,' ').trim().slice(0,110);}
    catch{ /* un corps illisible ne vaut pas une panne de plus */ }
    const error=new Error('http_'+response.statusCode+(detail?' '+detail:''));error.status=response.statusCode;throw error;}
  return response.body;
};
const rpc=(name,body={})=>request({method:'POST',url:SB_URL+'/rest/v1/rpc/'+name,headers:sbHeaders,body});
const db=(path,method='GET',body,extra={})=>request({method,url:SB_URL+'/rest/v1/'+path,headers:{...sbHeaders,...extra},...(body!==undefined?{body}:{})});
const serviceAuth=async headers=>{
  const key=headers?.apikey||String(headers?.authorization||'').replace(/^Bearer\s+/i,'');
  if(!key)return false;
  const backendHeaders={apikey:key,'Content-Type':'application/json',...(!key.startsWith('sb_')?{Authorization:'Bearer '+key}:{})};
  try{return await request({method:'POST',url:SB_URL+'/rest/v1/rpc/streetwear_service_ready',headers:backendHeaders,body:{},timeout:5000})===true;}
  catch{return false;}
};
const failResult=(reason,http_status=400)=>[{json:{ok:false,reason,http_status}}];
const ticketResult=ticket=>[{json:{...ticket,http_status:ticket.ok?202:(ticket.reason==='not_found'?404:200)}}];
const checkpoint=(ticket,data,wait=false)=>rpc('streetwear_checkpoint',{p_cloth:ticket.cloth.id,p_stage:ticket.stage,p_token:ticket.token,p_data:data,p_wait:wait});
const complete=(ticket,result={})=>rpc('streetwear_complete',{p_cloth:ticket.cloth.id,p_stage:ticket.stage,p_token:ticket.token,p_result:result});
const fail=(ticket,code,retry=false)=>rpc('streetwear_fail',{p_cloth:ticket.cloth.id,p_stage:ticket.stage,p_token:ticket.token,p_code:String(code).slice(0,160),p_retry:retry});
const callFlow=(path,body)=>request({method:'POST',url:N8N_URL+'/webhook/'+path,headers:sbHeaders,body,timeout:10000});
const refreshAsset=body=>request({method:'POST',url:SB_URL+'/functions/v1/streetwear-assets',headers:sbHeaders,body});
const tg=(method,body)=>request({method:'POST',url:'https://api.telegram.org/bot'+$env.TG_TOKEN+'/'+method,body});
const escapeHtml=value=>String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// SHA-256 only derives a separate provider webhook token; it never signs artwork.
function sha256(ascii){
  const rightRotate=(value,amount)=>(value>>>amount)|(value<<(32-amount));
  const maxWord=2**32,words=[],bitLength=ascii.length*8;
  let hash=[],constants=[],primeCounter=0;
  const composite={};
  for(let candidate=2;primeCounter<64;candidate++)if(!composite[candidate]){
    for(let i=0;i<313;i+=candidate)composite[i]=candidate;
    hash[primeCounter]=(Math.sqrt(candidate)*maxWord)|0;
    constants[primeCounter++]=(Math.cbrt(candidate)*maxWord)|0;
  }
  ascii+='\x80';while(ascii.length%64!==56)ascii+='\x00';
  for(let i=0;i<ascii.length;i++)words[i>>2]|=ascii.charCodeAt(i)<<(24-(i%4)*8);
  words.push((bitLength/maxWord)|0,bitLength);
  hash=hash.slice(0,8);
  for(let j=0;j<words.length;){
    const w=words.slice(j,j+=16),oldHash=hash.slice();
    for(let i=0;i<64;i++){
      const w15=w[i-15],w2=w[i-2],a=hash[0],e=hash[4];
      const temp1=hash[7]+(rightRotate(e,6)^rightRotate(e,11)^rightRotate(e,25))+((e&hash[5])^((~e)&hash[6]))+constants[i]+
        (w[i]=i<16?w[i]:(w[i-16]+(rightRotate(w15,7)^rightRotate(w15,18)^(w15>>>3))+w[i-7]+(rightRotate(w2,17)^rightRotate(w2,19)^(w2>>>10)))|0);
      const temp2=(rightRotate(a,2)^rightRotate(a,13)^rightRotate(a,22))+((a&hash[1])^(a&hash[2])^(hash[1]&hash[2]));
      hash=[(temp1+temp2)|0,a,hash[1],hash[2],(hash[3]+temp1)|0,hash[4],hash[5],hash[6]];
    }
    for(let i=0;i<8;i++)hash[i]=(hash[i]+oldHash[i])|0;
  }
  return hash.map(value=>(value>>>0).toString(16).padStart(8,'0')).join('');
}

const ticket=$input.first().json;
if(!ticket.ok)return [];
// ----- la decision du curateur sur un brouillon deja cree -----
if(ticket.route==='ship'||ticket.route==='hold'){
  const c=ticket.cloth;
  if(ticket.callback_id)try{await tg('answerCallbackQuery',{callback_query_id:ticket.callback_id,
    text:ticket.route==='ship'?'Sending to print\u2026':'Kept on hold.'});}catch{}
  let etat='on hold';
  if(ticket.route==='ship'){
    const r=await request({method:'POST',url:'https://api.printful.com/orders/'+encodeURIComponent(c.printful_order_id)+'/confirm',headers:pfHeaders});
    etat=String((r&&r.result&&r.result.status)||'pending');
  }
  const verdict=(ticket.route==='ship'?'\u2713 SENT TO PRINT \u2014 ':'\u23f8 ON HOLD \u2014 ')+String(c.name||'')+' \u00b7 Printful '+etat;
  if(ticket.message_id){
    try{await tg('editMessageCaption',{chat_id:$env.TG_CHAT,message_id:ticket.message_id,caption:verdict});}
    catch{ try{await tg('editMessageText',{chat_id:$env.TG_CHAT,message_id:ticket.message_id,text:verdict});}catch{} }
  }
  return [{json:{ok:true,cloth_id:c.id,route:ticket.route,printful_status:etat}}];
}
const cloth=ticket.cloth;
try{
  let order;
  try{order=(await request({url:'https://api.printful.com/orders/@'+cloth.id,headers:pfHeaders})).result;}
  catch(error){if(error.status!==404)throw error;}
  if(!order){
    if(ticket.job.data.order_request_started)throw new Error('printful_outcome_unknown');
    const support=(await db('totehm_cloth_support?id=eq.'+cloth.garment_id+'&select=*'))[0];
    const variant=support?.printful_variant_map?.[cloth.size];
    if(!variant?.sync_variant_id)throw new Error('variant_not_found');
    const area=support.print_area||{},placement=String(area.placement||'back');
    if(!/^[a-z0-9_]+$/.test(placement))throw new Error('print_placement');
    const fileType=area.method==='embroidery'?'embroidery_'+placement:placement;
    const address=cloth.shipping?.address||{};
    if(!cloth.shipping?.name||!address.line1||!address.city||!address.country||!address.postal_code)throw new Error('shipping_missing');
    const signed=await refreshAsset({cloth_id:cloth.id,purpose:'print'});
    const files=(variant.files||[]).filter(f=>f.type!==fileType&&f.type!=='preview'&&f.url)
      .map(f=>({type:f.type,url:f.url}));
    files.push({type:fileType,url:signed.url});
    await checkpoint(ticket,{order_request_started:true,external_id:cloth.id});
    const result=await request({method:'POST',url:'https://api.printful.com/orders?confirm=false',headers:pfHeaders,body:{
      external_id:cloth.id,
      recipient:{name:cloth.shipping.name,email:cloth.email,address1:address.line1,address2:address.line2||'',
        city:address.city,state_code:address.state||'',country_code:address.country,zip:address.postal_code},
      items:[{sync_variant_id:variant.sync_variant_id,name:'TOTEHM — '+cloth.name,quantity:1,files}],
    }});
    order=result.result;
  }
  if(!order?.id||String(order.external_id)!==cloth.id)throw new Error('printful_order_mismatch');
  if(!await complete(ticket,{order_id:String(order.id),printful_status:order.status||'draft'}))throw new Error('printful_lease');
  // 04/11 (Wah) : « mon Telegram ferait office de controle qualite ». Le brouillon est
  // pose, rien n'est fabrique : on MONTRE l'imprime sur le vetement, l'adresse et la
  // taille, et on attend un geste. Printful joint un fichier `preview` a la commande ;
  // s'il n'est pas encore pret, on relit la commande une fois avant de s'en passer.
  let apercu=null;
  for(let essai=0;essai<2&&!apercu;essai++){
    const items=(order&&order.items)||[];
    for(const item of items)for(const f of (item.files||[]))
      if(f&&f.type==='preview'&&(f.preview_url||f.thumbnail_url))apercu=f.preview_url||f.thumbnail_url;
    if(!apercu&&essai===0)try{order=(await request({url:'https://api.printful.com/orders/@'+cloth.id,headers:pfHeaders})).result;}catch{break;}
  }
  const adr=(cloth.shipping&&cloth.shipping.address)||{};
  const legende='<b>QUALITY CHECK</b>\n'+
    '<b>'+escapeHtml(String(cloth.name||''))+'</b> \u00b7 size '+escapeHtml(String(cloth.size||''))+'\n'+
    escapeHtml(String((cloth.shipping&&cloth.shipping.name)||''))+'\n'+
    escapeHtml([adr.line1,adr.line2,adr.postal_code,adr.city,adr.country].filter(Boolean).join(', '))+'\n\n'+
    'Printful draft #'+escapeHtml(String(order.id))+(apercu?'':' \u2014 no mockup yet')+'\n'+
    'Nothing is printed or charged until you send it.';
  const clavier={inline_keyboard:[[{text:'SEND TO PRINT',callback_data:'ship:'+cloth.id},
    {text:'HOLD',callback_data:'hold:'+cloth.id}]]};
  try{
    if(apercu)await tg('sendPhoto',{chat_id:$env.TG_CHAT,photo:apercu,caption:legende,parse_mode:'HTML',reply_markup:clavier});
    else await tg('sendMessage',{chat_id:$env.TG_CHAT,text:legende,parse_mode:'HTML',reply_markup:clavier});
  }catch{ /* le brouillon existe : un envoi rate ne le defait pas */ }
  return [{json:{ok:true,cloth_id:cloth.id,printful_order_id:String(order.id),printful_status:order.status||'draft'}}];
}catch(error){
  const code=String(error.message||'printful_failed');
  await fail(ticket,code,true);
  throw new Error('Streetwear Printful failed: '+code);
}

