const input=$input.first().json,body=input.body||{};
if(!await serviceAuth(input.headers))return failResult('unauthorized',401);
if(!uuid(body.cloth_id))return failResult('cloth_id');
// 04/11 (Wah) : Telegram fait office de CONTROLE QUALITE. Le brouillon Printful existe
// deja (`confirm=false` : rien n'est fabrique ni facture). Ce second appel ne reclame
// rien — il porte la DECISION prise sur une commande deja creee, donc pas de bail.
if(body.decision==='ship'||body.decision==='hold'){
  const cloth=(await db('totehm_clothes?id=eq.'+body.cloth_id+'&select=id,name,size,status,printful_order_id'))[0];
  if(!cloth)return failResult('not_found',404);
  if(!cloth.printful_order_id)return failResult('no_draft',200);
  return [{json:{ok:true,route:body.decision,cloth:cloth,callback_id:body.callback_id||null,
    message_id:body.message_id||null,http_status:202}}];
}
return ticketResult(await rpc('streetwear_claim',{p_cloth:body.cloth_id,p_stage:'printful',p_concept:null}));

return [{ json: {
  ...$input.first().json,
  SB_KEY: process.env.SB_KEY,
  PRINTFUL_TOKEN: process.env.PRINTFUL_TOKEN
}}];
